import { useEffect, useState } from 'react';
import { Navigate, useNavigate } from 'react-router-dom';
import type { LanguageCode, ModeId } from '@lexpad/core';
import { ADD_WORD_PATH } from '@/components/layout/nav.js';
import { PlaceHead } from '@/components/layout/PlaceHead.js';
import { Button } from '@/components/ui/Button.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { Icon } from '@/components/ui/Icon.js';
import { Skeleton } from '@/components/ui/Skeleton.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { useKeepScroll } from '@/lib/useKeepScroll.js';
import { refreshSrs } from '@/sync/srs.js';
import { MODE_ICONS, fewWordsBody, shownModes, type Blocker } from './data.js';
import { GameList } from './GameList.js';
import { useOpenModes } from './useOpenModes.js';
import styles from './Games.module.css';

/** Where somebody lands at /games while no game is switched on for the account. */
const WITHOUT_GAMES = '/decks';

/**
 * Games and drills (SRS v2 phase E), a place of its own since 2026-10-09:
 * tester feedback found Today's "Games and drills" and "Decks" opening the
 * same screen, because the games were a section at the top of Decks.
 *
 * It lists what can run here, from the same answer Today counts
 * (`useOpenModes`). Nothing can, and it says why for each one, with the
 * way to more words. With every mode switched off for the account there
 * is no games screen at all: the address goes to Decks, replacing itself,
 * so nobody is shown a place that does not exist for them.
 */
export function Games(): React.JSX.Element {
  const { view, open, closed, settled } = useOpenModes();
  // Back from a game lands where the reader was.
  useKeepScroll();
  // Somebody who followed a link here while signed out arrives before the
  // server has said whether the games are on. Not asked yet is not "off":
  // ask once, and only if that fails too is there nothing to show here.
  const unknown = view.ready && !view.srsKnown;
  const [askFailed, setAskFailed] = useState(false);
  useEffect(() => {
    if (!unknown) return undefined;
    let live = true;
    void refreshSrs()
      .catch(() => null)
      .then((answer) => {
        if (live && answer === null) setAskFailed(true);
      });
    return () => {
      live = false;
    };
  }, [unknown]);

  const off = view.ready && (view.srsKnown || askFailed) && shownModes(view.srs).length === 0;
  if (off) return <Navigate to={WITHOUT_GAMES} replace />;

  const waiting = !view.ready || !view.srsKnown || (open.length === 0 && !settled);
  return (
    <main className={styles.screen}>
      <PlaceHead title={t('modes.title')} />
      <p className={styles.lead}>{t('games.lead')}</p>
      {waiting ? (
        <>
          <Skeleton lines={4} />
          <span className="sr-only" role="status">
            {t('state.loading')}
          </span>
        </>
      ) : open.length > 0 ? (
        <GameList view={view} open={open} />
      ) : (
        <NoGames closed={closed} lang={view.notebook?.targetLang ?? 'en'} />
      )}
    </main>
  );
}

/**
 * Nothing can run here. Most often the notebook is too small, and the
 * answer is a few more words; a voice or a microphone missing on this
 * device is said as that, with no offer to add words that would not help.
 */
function NoGames({
  closed,
  lang,
}: {
  closed: { mode: ModeId; why: Blocker }[];
  lang: LanguageCode;
}): React.JSX.Element {
  const navigate = useNavigate();
  const needsWords = closed.some((entry) => entry.why === 'few');
  const language = LANGUAGE_NAMES[lang];
  return (
    <div className={styles.none}>
      <EmptyState
        compact
        icon={needsWords ? 'notebook' : 'computer'}
        tone="quiet"
        title={needsWords ? t('modes.fewTitle') : t('games.noneDeviceTitle')}
        body={needsWords ? t('games.noneBody') : t('games.noneDeviceBody')}
        actions={
          needsWords ? (
            <Button
              onClick={() => {
                void navigate(ADD_WORD_PATH);
              }}
            >
              {t('add.title')}
            </Button>
          ) : undefined
        }
      />
      <h2 className={styles.whyTitle}>{t('games.why')}</h2>
      <ul className={styles.why}>
        {closed.map(({ mode, why }) => (
          <li key={mode} className={styles.reason}>
            <span className={styles.reasonIcon} aria-hidden="true">
              <Icon name={MODE_ICONS[mode]} size={16} weight={1.9} />
            </span>
            <span>{reasonOf(mode, why, language)}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/** One plain sentence: what a mode needs that this notebook or device lacks. */
function reasonOf(mode: ModeId, why: Blocker, language: string): string {
  if (why === 'noVoice') return t('modes.noVoice', { language });
  if (why === 'noMic') return t('modes.noMic', { language });
  if (mode === 'sayIt' || mode === 'sentence') {
    const key: MessageKey = mode === 'sayIt' ? 'modes.fewSayIt' : 'modes.fewSentence';
    return t(key, fewWordsBody(mode).values);
  }
  const few = fewWordsBody(mode);
  return t(few.key as MessageKey, few.values);
}
